#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    const long long num = 998244353;
    long long n, k;
    cin >> n >> k;

    vector<long long> factorials(200001);
    factorials[0] = 1;
    long long factorialProduct = 1;
    for (int i = 1; i <= 200000; i++) {
        factorialProduct = (factorialProduct * i) % num;
        factorials[i] = factorialProduct;
    }

    auto power = [&](long long base, long long exp, long long mod) -> long long {
        long long result = 1;
        long long b = base % mod;
        long long e = exp;
        while (e > 0) {
            if (e & 1) {
                result = (result * b) % mod;
            }
            b = (b * b) % mod;
            e >>= 1;
        }
        return result;
    };

    long long total = 0;
    for (int i = 0; i < n - k; i++) {
        long long comb = factorials[n - k];
        comb = (comb * power(factorials[i], num - 2, num)) % num;
        comb = (comb * power(factorials[n - k - i], num - 2, num)) % num;
        long long term = power(n - k - i, n, num);
        if (i % 2 == 0) {
            total = (total + comb * term) % num;
        } else {
            total = (total - comb * term) % num;
        }
    }
    if (k >= n) {
        cout << 0 << "\n";
    } else {
        if (k != 0) {
            total = (total * 2) % num;
        }
        total = (total * factorials[n]) % num;
        total = (total * power(factorials[k], num - 2, num)) % num;
        total = (total * power(factorials[n - k], num - 2, num)) % num;
        total = (total + num) % num; // ensure non-negative
        cout << total << "\n";
    }
    return 0;
}

